// Most error core properties are not enumerable
export const setNonEnumProp = (object, propName, value) => {
  // eslint-disable-next-line fp/no-mutating-methods
  Object.defineProperty(object, propName, {
    value,
    enumerable: false,
    writable: true,
    configurable: true,
  })
}

