import { deepClone } from './clone.js'
import { getPluginOpts } from './get.js'
import { mergeMethodOpts } from './method.js'

// Retrieve, validate and normalize all options for a given plugin.
// Those are passed to `plugin.properties|instanceMethods.*`.
// We pass whether the `options` object is partial or not using `full`:
//  - This allows validation|normalization that requires options to be full,
//    such as:
//     - Required properties
//     - Properties depending on others
//  - While still encouraging validation to be performed as early as possible
//     - As opposed to splitting `getOptions()` into two different methods,
//       since that might encourage using only the method with the full
//       `options` object, which would prevent any early validation
// We pass positional arguments to `plugin.isOptions()` and `getOptions()` as
// opposed to the object passed to other methods since:
//  - Those two methods are simpler and more functional
//  - This makes it clear that `options` is post-getOptions
// `getOptions()` is meant for error instance-agnostic logic:
//  - This is because it is called early when classes are being defined
//  - `info.*` is not available
//  - Error-specific logic should be inside other plugin methods instead
// Any validation|normalization specific to a method should be done inside that
// method, as opposed to inside `plugin.getOptions()`.
// Plugins should avoid:
//  - Letting options be optionally a function: class constructors can be used
//    for this, by manipulating `options` and passing it to `super()`
//  - Using non-JSON serializable options, unless unavoidable
// Plugin options correspond to their `name`:
//  - It should match the package name
//  - This convention is simple to understand
//  - This promotes a single option name per plugin, which reduces the potential
//    for name conflict
//  - This reduces cross-plugin dependencies since they cannot easily reference
//    each other, keeping them decoupled from each other
export const finalizePluginsOpts = ({
  pluginsOpts,
  methodOpts,
  plugins,
  plugin,
}) => {
  const pluginsOptsA = mergeMethodOpts(pluginsOpts, methodOpts, plugins)
  const pluginsOptsB = deepClone(pluginsOptsA)
  const options = getPluginOpts({
    pluginsOpts: pluginsOptsB,
    plugin,
    full: true,
  })
  return options
}

src/plugins/properties/assign.js.source:
import { excludeKeys } from 'filter-obj'
import setErrorMessage from 'set-error-message'
import setErrorProps from 'set-error-props'
import setErrorStack from 'set-error-stack'

import { getPluginsMethodNames } from '../instance/main.js'

// `plugin.properties()` returns an object of properties to set.
// `undefined` values delete properties.
// Those are shallowly merged.
// Many properties are ignored:
//  - error core properties (except for `message` and `stack`)
//  - reserved top-level properties like `wrap`
//  - instance methods
// Setting those does not throw since:
//  - `plugin.properties()`'s return value might be dynamically generated
//    making it cumbersome for user to filter those.
//  - Throwing errors at runtime should be done with care since this would
//    happen during error handling time
export const assignError = (
  error,
  { message, stack, ...newProps },
  plugins,
) => {
  if (stack !== undefined) {
    setErrorStack(error, stack)
  }

  if (message !== undefined) {
    setErrorMessage(error, message)
  }

  if (Reflect.ownKeys(newProps).length === 0) {
    return
  }

  const keys = excludeKeys(newProps, [
    ...OMITTED_PROPS,
    ...getPluginsMethodNames(plugins),
  ])
  setErrorProps(error, keys)
}

const OMITTED_PROPS = ['wrap', 'constructorArgs']

src/utils/subclass.js.source:
// Check if `ErrorClass` is a subclass of `ParentClass`.
// We encourage `instanceof` over `error.name` for checking since this:
//  - Prevents name collisions with other libraries
//  - Allows checking if any error came from a given library
//  - Includes error classes in the exported interface explicitly instead of
//    implicitly, so that users are mindful about breaking changes
//  - Bundles classes with TypeScript documentation, types and autocompletion
//  - Encourages documenting error types
// Checking class with `error.name` is still supported, but not documented
//  - Since it is widely used and can be better in specific cases
// This also provides with namespacing, i.e. prevents classes of the same name
// but in different libraries to be considered equal. As opposed to the
// following alternatives:
//  - Namespacing all error names with a common prefix since this:
//     - Leads to verbose error names
//     - Requires either an additional option, or guessing ambiguously whether
//       error names are meant to include a namespace prefix
//  - Using a separate `namespace` property: this adds too much complexity and
//    is less standard than `instanceof`
export const isSubclass = (ErrorClass, ParentClass) =>
  ParentClass === ErrorClass || isProtoOf.call(ParentClass, ErrorClass)

const { isPrototypeOf: isProtoOf } = Object.prototype

