const { shouldPrefixCause } = require('../../../src/merge/prefix');

describe('shouldPrefixCause', () => {
  let ErrorClass;

  beforeEach(() => {
    ErrorClass = class CustomError extends Error {
      constructor(message) {
        super(message);
        this.name = 'CustomError';
      }
    };
  });

  it('should throw TypeError if error is not an object', () => {
    expect(() => shouldPrefixCause(null, ErrorClass)).toThrow(TypeError);
    expect(() => shouldPrefixCause(undefined, ErrorClass)).toThrow(TypeError);
    expect(() => shouldPrefixCause('string', ErrorClass)).toThrow(TypeError);
    expect(() => shouldPrefixCause(123, ErrorClass)).toThrow(TypeError);
  });

  it('should throw TypeError if error does not have a cause property', () => {
    const error = new Error('Main error');
    expect(() => shouldPrefixCause(error, ErrorClass)).toThrow(TypeError);
  });

  it.skip('should return false if ErrorClass is not a function', () => {
    const cause = new Error('Cause');
    const error = new Error('Main error');
    error.cause = cause;

    expect(shouldPrefixCause(error, 'NotAFunction')).toBe(false);
    expect(shouldPrefixCause(error, {})).toBe(false);
    expect(shouldPrefixCause(error, null)).toBe(false);
  });

  it('should return false if cause does not have a name property', () => {
    const error = new Error('Main error');
    const cause = {};
    error.cause = cause;

    expect(shouldPrefixCause(error, ErrorClass)).toBe(false);
  });

  it('should return false if cause name is empty or not a string', () => {
    const error = new Error('Main error');
    const cause = new Error('Cause');
    cause.name = '';
    error.cause = cause;

    expect(shouldPrefixCause(error, ErrorClass)).toBe(false);

    const cause2 = new Error('Cause');
    cause2.name = null;
    error.cause = cause2;
    expect(shouldPrefixCause(error, ErrorClass)).toBe(false);
  });

  it.skip('should return true if cause name matches ErrorClass name (useful name)', () => {
    const error = new Error('Main error');
    // Create a cause that is an instance of ErrorClass
    const cause = new ErrorClass('Cause error');
    // Ensure the name property is set correctly to match the class name
    expect(cause.name).toBe('CustomError');
    error.cause = cause;

    expect(shouldPrefixCause(error, ErrorClass)).toBe(true);
  });

  it('should return true if cause name differs from constructor name', () => {
    const error = new Error('Main error');
    const cause = new Error('Cause');
    cause.name = 'WrappedError';
    error.cause = cause;

    expect(shouldPrefixCause(error, ErrorClass)).toBe(true);
  });

  it('should return false if cause name is generic and matches constructor name (e.g. Error)', () => {
    const error = new Error('Main error');
    const cause = new Error('Cause');
    error.cause = cause;

    expect(shouldPrefixCause(error, ErrorClass)).toBe(false);
  });

  it('should return true if cause name matches ErrorClass name but differs from constructor name', () => {
    const error = new Error('Main error');
    const GenericError = class extends Error {};
    const cause = new GenericError();
    cause.name = 'CustomError';

    error.cause = cause;

    expect(shouldPrefixCause(error, ErrorClass)).toBe(true);
  });

  it('should return true if cause matches ErrorClass and is a useful name', () => {
    const AnotherError = class AnotherError extends Error {};
    const error = new Error('Main error');
    const cause = new AnotherError('Cause');

    error.cause = cause;
    expect(shouldPrefixCause(error, AnotherError)).toBe(true);
  });

  it('should return false if cause is a standard Error and ErrorClass is different', () => {
    const error = new Error('Main error');
    const cause = new Error('Standard cause');
    error.cause = cause;

    expect(shouldPrefixCause(error, ErrorClass)).toBe(false);
  });
});

