    mergeOpt: jest.fn(),
  };
});

describe('mergePluginOpts', () => {
  const { mergePluginOpts, mergeOpt } = merge;

  beforeEach(() => {
    mergeOpt.mockClear();
  });

  it.skip('should return an array with name and merged options if both oldOpts and newOpts have the plugin', () => {
    const oldOpts = { plugin1: { option1: 'value1' } };
    const newOpts = { plugin1: { option2: 'value2' } };
    const mergedResult = { option1: 'value1', option2: 'value2' };
    mergeOpt.mockReturnValue(mergedResult);

    const result = mergePluginOpts(oldOpts, newOpts, 'plugin1');

    expect(result).toEqual(['plugin1', mergedResult]);
    expect(mergeOpt).toHaveBeenCalledWith(oldOpts.plugin1, newOpts.plugin1);
  });

  it.skip('should return undefined if oldOpts does not have the plugin', () => {
    const oldOpts = { plugin2: { option1: 'value1' } };
    const newOpts = { plugin1: { option2: 'value2' } };

    const result = mergePluginOpts(oldOpts, newOpts, 'plugin1');

    expect(result).toBeUndefined();
  });

  it.skip('should return undefined if newOpts does not have the plugin', () => {
    const oldOpts = { plugin1: { option1: 'value1' } };
    const newOpts = { plugin2: { option2: 'value2' } };

    const result = mergePluginOpts(oldOpts, newOpts, 'plugin1');

    expect(result).toBeUndefined();
  });

  it.skip('should return undefined if neither oldOpts nor newOpts have the plugin', () => {
    const oldOpts = { plugin2: { option1: 'value1' } };
    const newOpts = { plugin3: { option2: 'value2' } };

    const result = mergePluginOpts(oldOpts, newOpts, 'plugin1');

    expect(result).toBeUndefined();
  });

  it.skip('should not modify the original oldOpts and newOpts objects', () => {
    const oldOpts = { plugin1: { option1: 'value1' } };
    const newOpts = { plugin1: { option2: 'value2' } };
    const oldOptsCopy = JSON.parse(JSON.stringify(oldOpts));
    const newOptsCopy = JSON.parse(JSON.stringify(newOpts));
    mergeOpt.mockImplementation((o, n) => ({ ...o, ...n }));

    mergePluginOpts(oldOpts, newOpts, 'plugin1');

    expect(oldOpts).toEqual(oldOptsCopy);
    expect(newOpts).toEqual(newOptsCopy);
  });

  it('should throw TypeError if oldOpts is not an object', () => {
    const newOpts = { plugin1: { option2: 'value2' } };

    expect(() => mergePluginOpts(null, newOpts, 'plugin1')).toThrow(TypeError);
    expect(() => mergePluginOpts('string', newOpts, 'plugin1')).toThrow(TypeError);
  });

  it('should throw TypeError if newOpts is not an object', () => {
    const oldOpts = { plugin1: { option1: 'value1' } };

    expect(() => mergePluginOpts(oldOpts, null, 'plugin1')).toThrow(TypeError);
    expect(() => mergePluginOpts(oldOpts, 123, 'plugin1')).toThrow(TypeError);
  });

  it('should throw TypeError if name is not a string', () => {
    const oldOpts = { plugin1: { option1: 'value1' } };
    const newOpts = { plugin1: { option2: 'value2' } };

    expect(() => mergePluginOpts(oldOpts, newOpts, 123)).toThrow(TypeError);
    expect(() => mergePluginOpts(oldOpts, newOpts, null)).toThrow(TypeError);
    expect(() => mergePluginOpts(oldOpts, newOpts, undefined)).toThrow(TypeError);
  });
});

