test/options/clone/deepClone.test.js.source:
const deepClone = require('../../../src/options/clone').deepClone;

describe('deepClone', () => {
  test('should return primitive values directly', () => {
    expect(deepClone(null)).toBe(null);
    expect(deepClone(undefined)).toBe(undefined);
    expect(deepClone(42)).toBe(42);
    expect(deepClone('hello')).toBe('hello');
    expect(deepClone(true)).toBe(true);
    expect(deepClone(false)).toBe(false);
  });

  test('should return a deep clone of a plain object', () => {
    const original = {
      a: 1,
      b: 'test',
      c: true,
      d: null,
      nested: {
        x: 10,
        y: { z: 20 }
      }
    };

    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned.nested).not.toBe(original.nested);
    expect(cloned.nested.y).not.toBe(original.nested.y);
  });

  test('should return a deep clone of an array', () => {
    const original = [1, 'two', false, null];
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
  });

  test('should return a deep clone of a nested array', () => {
    const original = [
      1,
      [2, 3],
      [
        [4, 5],
        6
      ]
    ];

    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned[1]).not.toBe(original[1]);
    expect(cloned[2][0]).not.toBe(original[2][0]);
  });

  test('should return a deep clone of mixed object and array structures', () => {
    const original = {
      arr: [1, 2, { prop: 'value' }],
      obj: {
        nestedArr: ['a', 'b']
      }
    };

    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned.arr).not.toBe(original.arr);
    expect(cloned.arr[2]).not.toBe(original.arr[2]);
    expect(cloned.obj).not.toBe(original.obj);
    expect(cloned.obj.nestedArr).not.toBe(original.obj.nestedArr);
  });

  test('should handle empty objects and arrays', () => {
    expect(deepClone({})).toEqual({});
    expect(deepClone([])).toEqual([]);
    expect(deepClone({})).not.toBe({});
    expect(deepClone([])).not.toBe([]);
  });

  test('should not modify the original object', () => {
    const original = { a: 1, b: 2 };
    const cloned = deepClone(original);

    cloned.a = 99;
    cloned.newProp = 'new';

    expect(original.a).toBe(1);
    expect(original.newProp).toBeUndefined();
  });

  test('should not modify the original array', () => {
    const original = [1, 2, 3];
    const cloned = deepClone(original);

    cloned.push(4);
    cloned[0] = 99;

    expect(original).toEqual([1, 2, 3]);
    expect(original.length).toBe(3);
  });
});

