const assignError = require('../../../../src/plugins/properties/assign').assignError;

describe('assignError', () => {
  let error;

  beforeEach(() => {
    error = new Error('Original error');
  });

  it('should assign message and stack to error object', () => {
    const props = {
      message: 'New error message',
      stack: 'Error: New error message\n    at test.js:1:1',
      customProp: 'value'
    };
    const plugins = [];

    assignError(error, props, plugins);

    expect(error.message).toBe('New error message');
    expect(error.stack).toBe('Error: New error message\n    at test.js:1:1');
    expect(error.customProp).toBe('value');
  });

  it('should assign properties from newProps to error object', () => {
    const props = {
      customProp: 'value',
      nested: { key: 'value' }
    };
    const plugins = [
      { instanceMethods: { pluginMethod: function() {}, anotherMethod: function() {} } },
      { instanceMethods: { someMethod: function() {} } }
    ];

    assignError(error, props, plugins);

    expect(error.customProp).toBe('value');
    expect(error.nested).toEqual({ key: 'value' });
  });

  it('should omit properties specified in the omitted list', () => {
    const props = {
      customProp: 'value',
      omitMe: 'should be omitted'
    };
    const plugins = [
      { instanceMethods: { omitMe: function() {} } }
    ];

    assignError(error, props, plugins);

    expect(error.customProp).toBe('value');
    expect(error.omitMe).toBeUndefined();
  });

  it('should handle empty props and plugins', () => {
    const plugins = [];

    assignError(error, {}, plugins);

    expect(error.message).toBe('Original error');
    expect(error.stack).toBeDefined();
