const validateEachPlugin = require('../../../../src/plugins/shape/duplicate');

describe('validateEachPlugin', () => {
  let pluginA, pluginB, MockError;

  beforeEach(() => {
    pluginA = {
      name: 'PluginA',
      fullName: 'PluginA',
      instanceMethods: { methodA: function() {} },
      staticMethods: { staticA: function() {} }
    };
    pluginB = {
      name: 'PluginB',
      fullName: 'PluginB',
      instanceMethods: { methodB: function() {} },
      staticMethods: { staticB: function() {} }
    };

    MockError = function() {};
  });

  it.skip('should not throw when plugins have different names and no overlapping methods', () => {
    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, MockError);
    }).not.toThrow();
  });

  it.skip('should not throw when comparing the same plugin instance (indexA === indexB)', () => {
    expect(() => {
      validateEachPlugin(pluginA, pluginA, 0, 0, MockError);
    }).not.toThrow();
  });

  it('should throw TypeError if plugins have the same name', () => {
    pluginB.name = 'PluginA';
    pluginB.fullName = 'PluginA-Clone';

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, MockError);
    }).toThrow(TypeError);
  });

  it('should throw TypeError if plugins define the same instance method', () => {
    pluginB.instanceMethods.methodA = function() { return 'B'; };

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, MockError);
    }).toThrow(TypeError);
  });

  it('should throw TypeError if plugins define the same static method', () => {
    pluginB.staticMethods.staticA = function() { return 'B'; };

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, MockError);
    }).toThrow(TypeError);
  });

  it.skip('should handle empty method objects without throwing', () => {
    pluginA.instanceMethods = {};
    pluginA.staticMethods = {};
    pluginB.instanceMethods = {};
    pluginB.staticMethods = {};

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, MockError);
    }).not.toThrow();
  });

  it('should throw correctly when only one plugin has empty methods but the other defines conflicting names', () => {
    pluginB.instanceMethods.methodA = function() {};
    pluginA.staticMethods = {};

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, MockError);
    }).toThrow(TypeError);
  });
});

