const validatePluginName = require('../../../../src/plugins/shape/name').validatePluginName;

describe('validatePluginName', () => {
  // Use a valid name: lowercase letters and digits only based on the error message
  const originalPlugin = { name: 'myplugin', version: '1.0.0' };

  test('should return a new object with fullName if plugin name is valid', () => {
    const result = validatePluginName(originalPlugin);

    expect(result).not.toBe(originalPlugin);
    expect(result.fullName).toBeDefined();
    expect(typeof result.fullName).toBe('string');
    expect(result.name).toBe(originalPlugin.name);
    expect(result.version).toBe(originalPlugin.version);
  });

  test('should throw TypeError if plugin is not an object', () => {
    expect(() => validatePluginName(null)).toThrow(TypeError);
    expect(() => validatePluginName(undefined)).toThrow(TypeError);
    expect(() => validatePluginName('string')).toThrow(TypeError);
    expect(() => validatePluginName(123)).toThrow(TypeError);
  });

  test('should throw TypeError if plugin does not have a name property', () => {
    expect(() => validatePluginName({})).toThrow(TypeError);
    expect(() => validatePluginName({ version: '1.0.0' })).toThrow(TypeError);
  });

  test('should throw TypeError if name property is not a string', () => {
    expect(() => validatePluginName({ name: 123 })).toThrow(TypeError);
    expect(() => validatePluginName({ name: null })).toThrow(TypeError);
    expect(() => validatePluginName({ name: {} })).toThrow(TypeError);
    expect(() => validatePluginName({ name: [] })).toThrow(TypeError);
  });

  test('should throw TypeError if name contains invalid characters (e.g. uppercase or special chars)', () => {
    expect(() => validatePluginName({ name: 'myPlugin' })).toThrow(TypeError);
    expect(() => validatePluginName({ name: 'my-plugin' })).toThrow(TypeError);
    expect(() => validatePluginName({ name: 'my plugin' })).toThrow(TypeError);
  });
});

