const normalizeClassOpts = require('../../../src/options/class').normalizeClassOpts;

describe('normalizeClassOpts', () => {
  class ParentError extends Error {}

  it('should return classOpts if it is a plain object', () => {
    const opts = { foo: 'bar' };
    expect(normalizeClassOpts(ParentError, opts)).toBe(opts);
  });

  it('should return empty object if classOpts is undefined', () => {
    expect(normalizeClassOpts(ParentError)).toEqual({});
  });

  it('should throw TypeError if classOpts is null', () => {
    expect(() => normalizeClassOpts(ParentError, null)).toThrow(TypeError);
  });

  it('should throw TypeError if classOpts is an array', () => {
    expect(() => normalizeClassOpts(ParentError, [1, 2, 3])).toThrow(TypeError);
  });

  it('should throw TypeError if classOpts is a function', () => {
    expect(() => normalizeClassOpts(ParentError, () => {})).toThrow(TypeError);
  });

  it('should throw TypeError if classOpts is a primitive', () => {
    expect(() => normalizeClassOpts(ParentError, 'string')).toThrow(TypeError);
    expect(() => normalizeClassOpts(ParentError, 123)).toThrow(TypeError);
    expect(() => normalizeClassOpts(ParentError, true)).toThrow(TypeError);
  });

  it('should include ParentError name in error message', () => {
    try {
      normalizeClassOpts(ParentError, 'invalid');
    } catch (e) {
      expect(e.message).toContain('ParentError');
    }
  });

  it('should treat instances of custom classes as invalid', () => {
    class CustomClass {}
    const instance = new CustomClass();
    expect(() => normalizeClassOpts(ParentError, instance)).toThrow(TypeError);
  });
});
